  /// string as if by `to-string`. MapLibre expression `concat`.
  public static func concat(_ arguments: TileflowExpression...) -> TileflowExpression {
    TileflowExpression(operator: "concat", arguments)
  }

  /// Returns the IETF language tag of the locale being used by the provided `collator`. This can be
  /// used to determine the default system locale, or to determine if a requested locale was
  /// successfully loaded. MapLibre expression `resolved-locale`.
  public static func resolvedLocale(_ arguments: TileflowExpression...) -> TileflowExpression {
    TileflowExpression(operator: "resolved-locale", arguments)
  }

  /// Returns an array of substrings formed by splitting an input string by a separator string.
  /// MapLibre expression `split`.
  public static func split(_ arguments: TileflowExpression...) -> TileflowExpression {
    TileflowExpression(operator: "split", arguments)
  }

  /// Returns a string formed by concatenating the elements of the input array, inserting a
  /// separator between each element. MapLibre expression `join`.
  public static func join(_ arguments: TileflowExpression...) -> TileflowExpression {
    TileflowExpression(operator: "join", arguments)
  }

  /// Interpolates linearly between the pair of stops just less than and just greater than the input
  /// MapLibre interpolation `linear`.
  public static func linear(_ arguments: TileflowExpression...) -> TileflowExpression {
    TileflowExpression(operator: "linear", arguments)
  }

  /// Interpolates exponentially between the stops just less than and just greater than the input.
  /// MapLibre interpolation `exponential`.
  public static func exponential(_ arguments: TileflowExpression...) -> TileflowExpression {
    TileflowExpression(operator: "exponential", arguments)
  }

  /// Interpolates using the cubic bézier curve defined by the given control points. MapLibre
  /// interpolation `cubic-bezier`.
  public static func cubicBezier(_ arguments: TileflowExpression...) -> TileflowExpression {
    TileflowExpression(operator: "cubic-bezier", arguments)
  }
}
